def compute(vars):
    average = (vars["v1"] + vars["v2"]) / 2
    return {
        "value": average,
        "trace": {
            "values": [vars["v1"], vars["v2"]],
            "count": 2,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
